{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';
import { resolve } from 'node:path';

const port = Number(process.env.PORT || 8080);
const databasePath = resolve(process.env.DB_PATH || 'workboard.sqlite');
const database = new DatabaseSync(databasePath);
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    archived INTEGER NOT NULL DEFAULT 0
  )
`);
database.exec(`
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0,
    priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))
  )
`);
database.exec('PRAGMA foreign_keys = ON');
// Upgrade databases created by the earlier task checkpoints.
const projectColumns = database.prepare('PRAGMA table_info(projects)').all();
if (!projectColumns.some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0');
}
const taskColumns = database.prepare('PRAGMA table_info(tasks)').all();
if (!taskColumns.some((column) => column.name === 'priority')) {
  database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal'");
}

const page = await readFile(new URL('./index.html', import.meta.url));

function sendJson(response, status, value) {
  response.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

async function readBody(request) {
  let body = '';
  for await (const chunk of request) body += chunk;
  return JSON.parse(body || '{}');
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, `http://${request.headers.host || 'localhost'}`);

  if (request.method === 'GET' && url.pathname === '/health') {
    return sendJson(response, 200, { status: 'ok' });
  }

  if (request.method === 'GET' && url.pathname === '/api/projects') {
    const projects = database.prepare(`
      SELECT p.id, p.name, p.archived,
        COUNT(t.id) AS totalCount,
        SUM(CASE WHEN t.completed = 1 THEN 1 ELSE 0 END) AS completedCount
      FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
      GROUP BY p.id ORDER BY p.id
    `).all().map((project) => ({
      ...project,
      archived: Boolean(project.archived),
      totalCount: Number(project.totalCount),
      completedCount: Number(project.completedCount || 0),
    }));
    return sendJson(response, 200, projects);
  }

  if (request.method === 'POST' && url.pathname === '/api/projects') {
    try {
      const { name } = await readBody(request);
      const trimmedName = typeof name === 'string' ? name.trim() : '';
      if (!trimmedName) return sendJson(response, 400, { error: 'Project name is required' });
      const result = database.prepare('INSERT INTO projects (name) VALUES (?)').run(trimmedName);
      return sendJson(response, 201, { id: Number(result.lastInsertRowid), name: trimmedName });
    } catch {
      return sendJson(response, 400, { error: 'Invalid request' });
    }
  }

  if (request.method === 'GET' && url.pathname.startsWith('/api/projects/')) {
    const parts = url.pathname.split('/');
    const id = Number(parts[3]);
    if (parts.length === 5 && parts[4] === 'tasks') {
      const project = Number.isInteger(id) && id > 0
        ? database.prepare('SELECT id FROM projects WHERE id = ?').get(id)
        : undefined;
      if (!project) return sendJson(response, 404, { error: 'Project not found' });
      const tasks = database.prepare('SELECT id, project_id AS projectId, title, completed, priority FROM tasks WHERE project_id = ? ORDER BY id').all(id);
      return sendJson(response, 200, tasks.map((task) => ({ ...task, completed: Boolean(task.completed) })));
    }
    const project = Number.isInteger(id) && id > 0
      ? database.prepare('SELECT id, name, archived FROM projects WHERE id = ?').get(id)
      : undefined;
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    return sendJson(response, 200, { ...project, archived: Boolean(project.archived) });
  }

  const projectUpdate = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (request.method === 'PATCH' && projectUpdate) {
    const id = Number(projectUpdate[1]);
    try {
      const update = await readBody(request);
      if (typeof update.archived === 'boolean') {
        const result = database.prepare('UPDATE projects SET archived = ? WHERE id = ?').run(update.archived ? 1 : 0, id);
        if (!result.changes) return sendJson(response, 404, { error: 'Project not found' });
        return sendJson(response, 200, { id, archived: update.archived });
      }
      if (typeof update.name === 'string') {
        const name = update.name.trim();
        if (!name) return sendJson(response, 400, { error: 'Project name is required' });
        const result = database.prepare('UPDATE projects SET name = ? WHERE id = ?').run(name, id);
        if (!result.changes) return sendJson(response, 404, { error: 'Project not found' });
        return sendJson(response, 200, { id, name });
      }
      return sendJson(response, 400, { error: 'Invalid project update' });
    } catch {
      return sendJson(response, 400, { error: 'Invalid request' });
    }
  }

  const taskRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
  if (taskRoute) {
    const projectId = Number(taskRoute[1]);
    const taskId = taskRoute[2] ? Number(taskRoute[2]) : null;
    const project = database.prepare('SELECT id FROM projects WHERE id = ?').get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    try {
      if (request.method === 'POST' && taskId === null) {
        const { title } = await readBody(request);
        const trimmedTitle = typeof title === 'string' ? title.trim() : '';
        if (!trimmedTitle) return sendJson(response, 400, { error: 'Task title is required' });
        const result = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)').run(projectId, trimmedTitle);
        return sendJson(response, 201, { id: Number(result.lastInsertRowid), projectId, title: trimmedTitle, completed: false, priority: 'Normal' });
      }
      if (request.method === 'PATCH' && taskId !== null) {
        const update = await readBody(request);
        if (typeof update.completed === 'boolean') {
          const result = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?').run(update.completed ? 1 : 0, taskId, projectId);
          if (!result.changes) return sendJson(response, 404, { error: 'Task not found' });
          return sendJson(response, 200, { id: taskId, projectId, completed: update.completed });
        }
        if (typeof update.title === 'string') {
          const title = update.title.trim();
          if (!title) return sendJson(response, 400, { error: 'Task title is required' });
          const result = database.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?').run(title, taskId, projectId);
          if (!result.changes) return sendJson(response, 404, { error: 'Task not found' });
          return sendJson(response, 200, { id: taskId, projectId, title });
        }
        if (['Low', 'Normal', 'High'].includes(update.priority)) {
          const result = database.prepare('UPDATE tasks SET priority = ? WHERE id = ? AND project_id = ?').run(update.priority, taskId, projectId);
          if (!result.changes) return sendJson(response, 404, { error: 'Task not found' });
          return sendJson(response, 200, { id: taskId, projectId, priority: update.priority });
        }
        return sendJson(response, 400, { error: 'Invalid task update' });
      }
    } catch {
      return sendJson(response, 400, { error: 'Invalid request' });
    }
  }

  if (request.method === 'GET' && (url.pathname === '/' || url.pathname.startsWith('/projects/'))) {
    response.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    return response.end(page);
  }

  response.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' });
  response.end('Not found');
});

server.listen(port, '0.0.0.0');
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    :root { color: #1e293b; background: #f5f7fa; font-family: system-ui, sans-serif; }
    body { margin: 0; }
    main { max-width: 760px; margin: 56px auto; padding: 0 24px; }
    h1 { margin: 0 0 28px; font-size: 2rem; }
    form, .project-row, .task-row { display: flex; gap: 12px; align-items: center; }
    form { margin-bottom: 24px; }
    label { font-weight: 600; }
    input { box-sizing: border-box; min-width: 0; flex: 1; padding: 10px 12px; border: 1px solid #cbd5e1; border-radius: 6px; font: inherit; }
    button { padding: 10px 14px; border: 0; border-radius: 6px; background: #2457d6; color: white; font: inherit; font-weight: 600; cursor: pointer; }
    button:hover { background: #1946b7; }
    .project-list { display: grid; gap: 10px; }
    .project-row { justify-content: space-between; padding: 14px 16px; border: 1px solid #dce2ea; border-radius: 8px; background: white; }
    .project-name { font-weight: 600; }
    .task-list { display: grid; gap: 10px; margin-top: 18px; }
    .task-row { justify-content: space-between; padding: 14px 16px; border: 1px solid #dce2ea; border-radius: 8px; background: white; }
    .task-row label { display: flex; align-items: center; gap: 10px; font-weight: 400; }
    .task-row input { flex: initial; width: 18px; height: 18px; }
    [role="alert"] { min-height: 1.5em; margin: -12px 0 16px; color: #b42318; }
    @media (max-width: 520px) { main { margin-top: 32px; } form { align-items: stretch; flex-direction: column; } }
  </style>
</head>
<body>
  <main id="app"></main>
  <script type="module">
    const app = document.querySelector('#app');

    async function getProjects() {
      const response = await fetch('/api/projects');
      return response.json();
    }

    function renderList(projects, alertMessage = '', selectedFilter = 'Active') {
      app.replaceChildren();
      const heading = document.createElement('h1');
      heading.textContent = 'Workboard';
      app.append(heading);

      const filterLabel = document.createElement('label');
      filterLabel.htmlFor = 'project-filter';
      filterLabel.textContent = 'Project filter';
      const filter = document.createElement('select');
      filter.id = 'project-filter';
      for (const value of ['Active', 'Archived']) {
        const option = document.createElement('option');
        option.value = value;
        option.textContent = value;
        filter.append(option);
      }
      filter.value = selectedFilter;

      const form = document.createElement('form');
      const label = document.createElement('label');
      label.htmlFor = 'project-name';
      label.textContent = 'Project name';
      const input = document.createElement('input');
      input.id = 'project-name';
      input.name = 'name';
      input.type = 'text';
      input.setAttribute('aria-label', 'Project name');
      const createButton = document.createElement('button');
      createButton.type = 'submit';
      createButton.textContent = 'Create project';
      form.append(label, input, createButton);
      form.addEventListener('submit', async (event) => {
        event.preventDefault();
        const name = input.value.trim();
        if (!name) {
          renderList(await getProjects(), 'Project name is required');
          return;
        }
        const response = await fetch('/api/projects', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ name }),
        });
        if (response.ok) renderList(await getProjects());
      });
      app.append(form);

      const alert = document.createElement('p');
      alert.setAttribute('role', 'alert');
      alert.textContent = alertMessage;
      app.append(alert);

      const list = document.createElement('section');
      list.className = 'project-list';
      for (const project of projects.filter((item) => item.archived === (filter.value === 'Archived'))) {
        const row = document.createElement('div');
        row.className = 'project-row';
        row.dataset.testid = 'project-row';
        const name = document.createElement('span');
        name.className = 'project-name';
        name.textContent = project.name;
        const open = document.createElement('button');
        open.type = 'button';
        open.textContent = 'Open project';
        open.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
        const summary = document.createElement('span');
        summary.dataset.testid = 'project-summary';
        summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
        const archive = document.createElement('button');
        archive.type = 'button';
        archive.textContent = project.archived ? 'Restore project' : 'Archive project';
        archive.addEventListener('click', async () => {
          const update = await fetch(`/api/projects/${project.id}`, {
            method: 'PATCH', headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ archived: !project.archived }),
          });
          if (update.ok) renderList(await getProjects());
        });
        row.append(name, summary, open, archive);
        list.append(row);
      }
      filter.addEventListener('change', () => renderList(projects, '', filter.value));
      app.insertBefore(filter, form);
      app.insertBefore(filterLabel, filter);
      app.append(list);
    }

    async function renderProject(id) {
      const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
      if (!response.ok) {
        app.textContent = 'Project not found';
        return;
      }
      const project = await response.json();
      app.replaceChildren();
      const pageAlert = document.createElement('p');
      pageAlert.setAttribute('role', 'alert');
      const back = document.createElement('button');
      back.type = 'button';
      back.textContent = 'Projects';
      back.addEventListener('click', () => { location.href = '/'; });
      const heading = document.createElement('h1');
      heading.textContent = project.name;
      const renameForm = document.createElement('form');
      const renameLabel = document.createElement('label');
      renameLabel.htmlFor = 'new-project-name';
      renameLabel.textContent = 'New project name';
      const renameInput = document.createElement('input');
      renameInput.id = 'new-project-name';
      renameInput.type = 'text';
      renameInput.value = project.name;
      renameInput.disabled = project.archived;
      const renameButton = document.createElement('button');
      renameButton.type = 'submit';
      renameButton.textContent = 'Rename project';
      renameButton.disabled = project.archived;
      renameForm.append(renameLabel, renameInput, renameButton);
      renameForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        const name = renameInput.value.trim();
        if (!name) {
          pageAlert.textContent = 'Project name is required';
          return;
        }
        const result = await fetch(`/api/projects/${encodeURIComponent(id)}`, {
          method: 'PATCH',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ name }),
        });
        if (result.ok) {
          project.name = name;
          heading.textContent = name;
          renameInput.value = name;
          pageAlert.textContent = '';
        }
      });
      const archivedNotice = document.createElement('p');
      if (project.archived) archivedNotice.textContent = 'Archived project';
      const form = document.createElement('form');
      const label = document.createElement('label');
      label.htmlFor = 'task-title';
      label.textContent = 'Task title';
      const input = document.createElement('input');
      input.id = 'task-title';
      input.type = 'text';
      const create = document.createElement('button');
      create.type = 'submit';
      create.textContent = 'Create task';
      create.disabled = project.archived;
      form.append(label, input, create);

      const filterLabel = document.createElement('label');
      filterLabel.htmlFor = 'task-filter';
      filterLabel.textContent = 'Task filter';
      const filter = document.createElement('select');
      filter.id = 'task-filter';
      for (const value of ['All', 'Open', 'Completed']) {
        const option = document.createElement('option');
        option.value = value;
        option.textContent = value;
        filter.append(option);
      }
      const priorityFilterLabel = document.createElement('label');
      priorityFilterLabel.htmlFor = 'priority-filter';
      priorityFilterLabel.textContent = 'Priority filter';
      const priorityFilter = document.createElement('select');
      priorityFilter.id = 'priority-filter';
      for (const value of ['All', 'Low', 'Normal', 'High']) {
        const option = document.createElement('option');
        option.value = value;
        option.textContent = value;
        priorityFilter.append(option);
      }
      const list = document.createElement('section');
      list.className = 'task-list';

      async function refreshTasks() {
        const tasksResponse = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`);
        if (!tasksResponse.ok) return;
        const tasks = await tasksResponse.json();
        list.replaceChildren();
        const matching = tasks.filter((task) =>
          (filter.value === 'All' || (filter.value === 'Completed' ? task.completed : !task.completed))
          && (priorityFilter.value === 'All' || task.priority === priorityFilter.value));
        for (const task of matching) {
          const row = document.createElement('div');
          row.className = 'task-row';
          row.dataset.testid = 'task-row';
          const taskLabel = document.createElement('label');
          const checkbox = document.createElement('input');
          checkbox.type = 'checkbox';
          checkbox.checked = task.completed;
          checkbox.disabled = project.archived;
          checkbox.setAttribute('aria-label', `Complete ${task.title}`);
          checkbox.addEventListener('change', async () => {
            const update = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${task.id}`, {
              method: 'PATCH',
              headers: { 'content-type': 'application/json' },
              body: JSON.stringify({ completed: checkbox.checked }),
            });
            if (update.ok) refreshTasks();
          });
          const title = document.createElement('span');
          title.textContent = task.title;
          taskLabel.append(checkbox, title);
          const renameForm = document.createElement('form');
          const renameInput = document.createElement('input');
          renameInput.type = 'text';
          renameInput.value = task.title;
          renameInput.setAttribute('aria-label', 'New task title');
          renameInput.disabled = project.archived;
          const renameButton = document.createElement('button');
          renameButton.type = 'submit';
          renameButton.textContent = 'Rename task';
          renameButton.disabled = project.archived;
          renameForm.append(renameInput, renameButton);
          renameForm.addEventListener('submit', async (event) => {
            event.preventDefault();
            const newTitle = renameInput.value.trim();
            if (!newTitle) {
              pageAlert.textContent = 'Task title is required';
              return;
            }
            const update = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${task.id}`, {
              method: 'PATCH',
              headers: { 'content-type': 'application/json' },
              body: JSON.stringify({ title: newTitle }),
            });
            if (update.ok) {
              pageAlert.textContent = '';
              await refreshTasks();
            }
          });
          const priority = document.createElement('select');
          priority.setAttribute('aria-label', 'Task priority');
          for (const value of ['Low', 'Normal', 'High']) {
            const option = document.createElement('option');
            option.value = value;
            option.textContent = value;
            priority.append(option);
          }
          priority.value = task.priority || 'Normal';
          priority.disabled = project.archived;
          priority.addEventListener('change', async () => {
            const update = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${task.id}`, {
              method: 'PATCH',
              headers: { 'content-type': 'application/json' },
              body: JSON.stringify({ priority: priority.value }),
            });
            if (!update.ok) priority.value = task.priority || 'Normal';
            else {
              task.priority = priority.value;
              await refreshTasks();
            }
          });
          row.append(taskLabel, renameForm, priority);
          list.append(row);
        }
      }
      filter.addEventListener('change', refreshTasks);
      priorityFilter.addEventListener('change', refreshTasks);

      priorityFilter.addEventListener('change', refreshTasks);
      form.addEventListener('submit', async (event) => {
        event.preventDefault();
        const title = input.value.trim();
        if (!title) {
          pageAlert.textContent = 'Task title is required';
          return;
        }
        const result = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ title }),
        });
        if (result.ok) {
          input.value = '';
          pageAlert.textContent = '';
          await refreshTasks();
        }
      });
      app.append(back, heading, renameForm, archivedNotice, form, pageAlert, filterLabel, filter,
        priorityFilterLabel, priorityFilter, list);
      refreshTasks();
    }

    const match = location.pathname.match(/^\/projects\/([^/]+)$/);
    if (match) renderProject(match[1]);
    else getProjects().then((projects) => renderList(projects));
  </script>
</body>
